import{_ as e,o as s,c as n,a3 as t}from"./chunks/framework.BkJHvlZ8.js";const u=JSON.parse('{"title":"提交与 AI 分析","description":"","frontmatter":{},"headers":[],"relativePath":"marketplace/submission.md","filePath":"marketplace/submission.md","lastUpdated":1787901540000}'),i={name:"marketplace/submission.md"};function o(p,a,l,r,c,d){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="提交与-ai-分析" tabindex="-1">提交与 AI 分析 <a class="header-anchor" href="#提交与-ai-分析" aria-label="Permalink to &quot;提交与 AI 分析&quot;">​</a></h1><h2 id="提交资料" tabindex="-1">提交资料 <a class="header-anchor" href="#提交资料" aria-label="Permalink to &quot;提交资料&quot;">​</a></h2><p>开发者在官网 <a href="/apehub-web/profile.html">个人中心</a> 创建插件草稿，填写插件标识、展示名称、介绍、分类、标签、USDT 定价、Logo、轮播图和 Demo 信息。创建插件只产生草稿，不会立即出现在市场。</p><h2 id="版本工作台" tabindex="-1">版本工作台 <a class="header-anchor" href="#版本工作台" aria-label="Permalink to &quot;版本工作台&quot;">​</a></h2><p>每个插件可以维护多个版本。上传 ZIP 时，平台会校验包结构、文件大小、<code>plugin.json</code> 和版本号；同一版本只保留一个当前安装包。文档、更新说明和兼容性信息都属于版本，而不是全局插件资料。</p><h2 id="ai-技术文档" tabindex="-1">AI 技术文档 <a class="header-anchor" href="#ai-技术文档" aria-label="Permalink to &quot;AI 技术文档&quot;">​</a></h2><p>上传包后先执行静态检查，再由 DeepSeek 根据文件树和源码摘要生成 Markdown。生成结果只写入当前版本草稿，开发者可以人工修改后再提交审核。</p><p>AI 分析不是自动放行机制：管理员仍需查看风险提示、源码文件、权限需求和版本文档。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>不要在插件包中提交 API Key、密码、令牌、私钥、生产数据库连接串或用户隐私数据。</p></div><h2 id="提交流程" tabindex="-1">提交流程 <a class="header-anchor" href="#提交流程" aria-label="Permalink to &quot;提交流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>创建插件 → 创建版本 → 上传安装包 → 静态检查</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>                    AI 生成文档（可重试）</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>                    人工完善 → 提交审核</span></span></code></pre></div><p>审核通过后还需要管理员单独执行“发布上架”，发布动作才会让版本进入公开市场。</p>`,12)])])}const m=e(i,[["render",o]]);export{u as __pageData,m as default};
